-- Fixture-only append-only Feature 30 history. No live source, provider, or product table is referenced.
CREATE OR REPLACE FUNCTION evidence_integrity_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'evidence integrity history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS evidence_integrity_runs(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS evidence_integrity_decisions(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES evidence_integrity_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS evidence_integrity_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key),FOREIGN KEY(operator_test_id,run_hash) REFERENCES evidence_integrity_runs(operator_test_id,run_hash));
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['evidence_integrity_runs','evidence_integrity_decisions','evidence_integrity_request_claims'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS evidence_integrity_immutable ON %I',tab); EXECUTE format('CREATE TRIGGER evidence_integrity_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION evidence_integrity_append_only()',tab); END LOOP; END $$;
CREATE INDEX IF NOT EXISTS evidence_integrity_run_scope_idx ON evidence_integrity_runs(operator_test_id,created_at);
